package com.personal.assistant.module.inbox.controller;
import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.inbox.dto.*;import com.personal.assistant.module.inbox.service.InboxConversionService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/inbox-conversions") public class InboxConversionController{private final InboxConversionService service;public InboxConversionController(InboxConversionService service){this.service=service;}private Long uid(){return SecurityContextHelper.currentUserId();}@PostMapping("/{id}")public ApiResponse<InboxConversionResponse>convert(@PathVariable Long id,@Valid @RequestBody InboxConversionRequest r){return ApiResponse.success(service.convert(uid(),id,r));}@PostMapping("/{id}/undo")public ApiResponse<Void>undo(@PathVariable Long id){service.undo(uid(),id);return ApiResponse.success();}@GetMapping("/{id}")public ApiResponse<InboxConversionResponse>result(@PathVariable Long id){return ApiResponse.success(service.result(uid(),id));}}
